void scsi_abort_command_handler(struct scsi_cmnd *cmd)
{
    struct sas_ha_struct *sha = cmd->device->host->hostdata;
    struct sas_rphy *rphy = dev_to_rphy(cmd->device->sdev_gendev.parent);
    struct sas_device *sdev = rphy ? &to_sas_end_device(rphy->rphy_dev) : NULL;
    struct domain_device *dev = sdev ? sdev->sas_device : NULL;

    if (!dev)
        return;

    if (dev->dev_type == SAS_SATA) {
        /* Defer to libata error handler */
        scsi_ata_done(cmd);
    } else {
        cmd->result = (DID_ABORT << 16);
        scsi_dma_unmap(cmd);
        cmd->scsi_done(cmd);
        list_del(&cmd->eh_entry);
    }
}

void scsi_abort_command_complete(struct scsi_cmnd *cmd)
{
    struct sas_hba *sas_hba = cmd->device->host->hostdata;
    struct sas_rphy *rphy = cmd->device->hostdata;
    struct sas_device *sas_dev = rphy ? rphy->device : NULL;
    bool is_sata = sas_dev && sas_dev->is_sata;

    if (is_sata) {
        cmd->result = DID_ABORT << 16;
        scsi_unblock_host(cmd->device->host);
        scsi_activate_cmnd(cmd);
        return;
    }

    cmd->result = DID_ABORT << 16;
    scsi_finish_command(cmd);
}

void scsi_abort_command_completion(struct scsi_cmnd *cmd)
{
    struct sas_hba *sas_hba = cmd->device->host->hostdata;
    struct sas_rphy *rphy = rcu_dereference(cmd->device->sdev_state);
    struct sas_address *addr = &rphy->identify.sas_address;
    struct domain_device *dev = sas_find_domain_device(sas_hba, addr->wwid, addr->sas_addr, GFP_ATOMIC);

    if (!dev) {
        scsi_dma_unmap(cmd);
        scsi_finish_command(cmd);
        return;
    }

    if (dev_is_sata(dev)) {
        cmd->result = (DID_ABORT << 16);
        scsi_dma_unmap(cmd);
        scsi_report_bus_reset(cmd->device->host, dev->sas_addr, 0);
        return;
    }

    scsi_dma_unmap(cmd);
    scsi_remove_from_error_queue(cmd);
    scsi_finish_command(cmd);
}

void scsi_cmd_abort_complete(struct scsi_cmnd *cmd)
{
    struct sas_ha *sha = cmd->device->host->hostdata;
    struct sas_rphy *rdev = cmd->device->hostdata;
    struct sas_device *sdev = rdev->sdev;

    if (cmd->eh_info.eh_status & EH_ABORTED)
        return;

    if (sdev->type == SAS_SATA_DEV) {
        ata_scsi_error_handler(cmd);
        return;
    }

    scsi_dma_unmap(cmd);
    cmd->result = DID_ABORT << 16;
    cmd->scsi_done(cmd);

    list_del_init(&cmd->eh_entry);
}

void scsi_command_abort_complete(struct scsi_cmnd *cmd)
{
    struct sas_ha *ha = cmd->device->host->hostdata;
    struct sas_rphy *rdev = cmd->device->hostdata;
    struct sas_phy *phy = rdev->phy;
    struct sas_end_device *end_dev = phy->endpoint->end_dev;

    if (end_dev && end_dev->sata_dev) {
        scsi_ata_end_request(cmd, -EIO, 0);
    } else {
        cmd->result = DID_ABORT << 16;
        scsi_finish_command(cmd);
        list_del(&cmd->eh_list);
    }
}
